WITH exploded AS (SELECT id, plan, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 64 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, plan, PERCENTILE_APPROX(tier_value, 0.9) AS tier_value_p90, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS tier_value_per_basic, COUNT(*) AS row_count FROM exploded GROUP BY 1, 2 HAVING ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) >= 0;
